# owner: platform
import unittest

from hourglass.rounding import round_labels
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_label(self):
        spans = [Span(541, 1034)]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_bad_steps(self):
        for step in (0, -5, 7):
            with self.assertRaises(ValueError):
                round_labels([Span(60, 120)], step)


if __name__ == "__main__":
    unittest.main()
